import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadCaveat = makeLoadFont('Caveat');

// Load Google Font at module level to ensure it's ready before frame 0
const { fontFamily: caveatFamily } = loadCaveat();



export type HandDrawnIconsProps = Record<string, any>;

// Helper component to animate SVG paths cleanly
const AnimatedPath: React.FC<{
  d: string;
  progress: number;
  strokeColor: string;
  strokeWidth: number;
}> = ({ d, progress, strokeColor, strokeWidth }) => {
  // evolvePath calculates the dasharray and dashoffset needed to draw the path
  const evolution = evolvePath(Math.max(0, Math.min(1, progress)), d);

  return (
    <path
      d={d}
      stroke={strokeColor}
      strokeWidth={strokeWidth}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeDasharray={evolution.strokeDasharray}
      strokeDashoffset={evolution.strokeDashoffset}
      style={{ transition: "none" }}
    />
  );
};

// Hand-drawn style SVG path definitions
const stopwatchPaths = [
  "M 50 15 C 75 12 90 30 85 55 C 80 80 60 90 35 85 C 10 80 12 60 15 35 C 18 10 35 12 50 15", // Wobbly circle
  "M 45 15 Q 50 5 55 15", // Top button
  "M 72 28 L 82 18", // Side button stem
  "M 78 15 L 85 22", // Side button cap
  "M 50 50 Q 48 35 52 25", // Minute hand
  "M 50 50 Q 55 52 65 48", // Second hand
  "M 49 50 A 1 1 0 1 0 49.1 50", // Center dot
];

const phonePaths = [
  "M 25 75 C 20 50 35 45 50 45 C 65 45 80 50 75 75 C 70 85 30 85 25 75", // Rotary base body
  "M 37 63 C 37 52 63 52 63 63 C 63 74 37 74 37 63", // Rotary dial outer circle
  "M 43 57 A 2 2 0 1 0 43.1 57", // Dial hole 1
  "M 50 55 A 2 2 0 1 0 50.1 55", // Dial hole 2
  "M 57 57 A 2 2 0 1 0 57.1 57", // Dial hole 3
  "M 60 63 A 2 2 0 1 0 60.1 63", // Dial hole 4
  "M 40 45 L 35 35", // Cradle left
  "M 60 45 L 65 35", // Cradle right
  "M 25 28 C 35 15 65 15 75 28", // Handset handle
  "M 20 38 L 32 32 L 25 24 Q 15 30 20 38", // Earpiece
  "M 80 38 L 68 32 L 75 24 Q 85 30 80 38", // Mouthpiece
  "M 25 75 C 10 80 10 65 20 65 C 30 65 10 50 20 50 C 30 50 25 40 20 38" // Curly cord
];

const calendarPaths = [
  "M 15 25 Q 50 23 85 25 Q 87 55 85 85 Q 50 87 15 85 Q 13 55 15 25", // Box
  "M 15 42 Q 50 39 85 42", // Header line
  "M 22 15 Q 28 10 28 25", // Binding loop 1
  "M 47 15 Q 53 10 53 25", // Binding loop 2
  "M 72 15 Q 78 10 78 25", // Binding loop 3
  // "Fully booked" X marks across the grid
  "M 25 55 L 35 65", "M 35 55 L 25 65",
  "M 50 55 L 60 65", "M 60 55 L 50 65",
  "M 75 55 L 85 65", "M 85 55 L 75 65",
  "M 25 75 L 35 85", "M 35 75 L 25 85",
  "M 50 75 L 60 85", "M 60 75 L 50 85",
  "M 75 75 L 85 85", "M 85 75 L 75 85",
];

const HandDrawnIcons: React.FC<HandDrawnIconsProps> = ({
  backgroundColor = "#fdfbf7", // Warm paper-like background
  transparentBackground = false,
  durationInSeconds = 8,
  strokeColor = "#2c2c2c", // Graphite ink color
  textColor = "#2c2c2c",
  strokeWidth = 3.5,
  stopwatchText = "3 minutes",
  phoneText = "9 seconds",
  calendarText = "fully booked out",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation stagger timings based on FPS
  // Item 1 (Stopwatch)
  const progress1 = interpolate(frame, [0, fps * 1.5], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textOpacity1 = interpolate(frame, [fps, fps * 1.5], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textY1 = spring({ fps, frame: frame - fps, config: { damping: 12 } });

  // Item 2 (Phone)
  const progress2 = interpolate(frame, [fps * 0.5, fps * 2.0], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textOpacity2 = interpolate(frame, [fps * 1.5, fps * 2.0], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textY2 = spring({ fps, frame: frame - fps * 1.5, config: { damping: 12 } });

  // Item 3 (Calendar)
  const progress3 = interpolate(frame, [fps * 1.0, fps * 2.5], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textOpacity3 = interpolate(frame, [fps * 2.0, fps * 2.5], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textY3 = spring({ fps, frame: frame - fps * 2.0, config: { damping: 12 } });

  const getTextStyle = (opacity: number, ySpring: number): React.CSSProperties => ({
    fontFamily: caveatFamily,
    fontSize: "72px",
    color: textColor,
    opacity,
    transform: `translateY(${interpolate(ySpring, [0, 1], [30, 0])}px)`,
    textAlign: "center",
    lineHeight: 1.2,
    maxWidth: "90%",
    wordWrap: "break-word",
    transition: "none",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: transparentBackground ? "transparent" : backgroundColor }}>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "space-evenly",
          width: "100%",
          height: "100%",
          padding: "0 5%",
          transition: "none",
        }}
      >
        {/* Stopwatch Section */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "20px", flex: 1, transition: "none" }}>
          <svg viewBox="0 0 100 100" style={{ width: "250px", height: "250px", overflow: "visible", transition: "none" }}>
            {stopwatchPaths.map((d, i) => (
              <AnimatedPath key={`stopwatch-${i}`} d={d} progress={progress1} strokeColor={strokeColor} strokeWidth={strokeWidth} />
            ))}
          </svg>
          <div style={getTextStyle(textOpacity1, textY1)}>{stopwatchText}</div>
        </div>

        {/* Phone Section */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "20px", flex: 1, transition: "none" }}>
          <svg viewBox="0 0 100 100" style={{ width: "250px", height: "250px", overflow: "visible", transition: "none" }}>
            {phonePaths.map((d, i) => (
              <AnimatedPath key={`phone-${i}`} d={d} progress={progress2} strokeColor={strokeColor} strokeWidth={strokeWidth} />
            ))}
          </svg>
          <div style={getTextStyle(textOpacity2, textY2)}>{phoneText}</div>
        </div>

        {/* Calendar Section */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "20px", flex: 1, transition: "none" }}>
          <svg viewBox="0 0 100 100" style={{ width: "250px", height: "250px", overflow: "visible", transition: "none" }}>
            {calendarPaths.map((d, i) => (
              <AnimatedPath key={`calendar-${i}`} d={d} progress={progress3} strokeColor={strokeColor} strokeWidth={strokeWidth} />
            ))}
          </svg>
          <div style={getTextStyle(textOpacity3, textY3)}>{calendarText}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default HandDrawnIcons;